insert into questions (id, area, topic, difficulty, relevance, competency, stem, options_text, correct_index, explanation, source_name, source_url, status) values
('q-001', 'Medicina', 'Cardiologia', 'Média', 'A', 'Diagnóstico', 'Um homem de 68 anos apresenta dispneia progressiva, ortopneia e edema maleolar. Qual é o exame inicial mais adequado para avaliar a suspeita de insuficiência cardíaca?', 'Ecocardiograma transtorácico|Angio-TC coronária|Prova de esforço|Holter de 24 horas', 0, 'O ecocardiograma avalia estrutura e função cardíacas e é central na confirmação e fenotipagem da insuficiência cardíaca.', 'ESC Guidelines - Heart Failure', 'https://www.escardio.org/Guidelines', 'Revista'),
('q-002', 'Pediatria', 'Infeciologia', 'Fácil', 'A', 'Gestão do doente', 'Uma criança de 3 anos apresenta febre, tosse metálica e estridor inspiratório ligeiro sem sinais de dificuldade respiratória. Qual é a abordagem inicial mais apropriada?', 'Dexametasona oral|Antibiótico endovenoso|Salbutamol nebulizado|Intubação imediata', 0, 'Na laringite aguda ligeira, uma dose de dexametasona reduz sintomas e necessidade de reavaliação.', 'DGS - Normas e orientações', 'https://www.dgs.pt/normas-orientacoes-e-informacoes/normas-e-circulares-normativas.aspx', 'Revista'),
('q-003', 'Cirurgia', 'Abdómen agudo', 'Difícil', 'A', 'Diagnóstico', 'Uma mulher de 74 anos com fibrilhação auricular apresenta dor abdominal súbita intensa, desproporcionada ao exame objetivo. Qual é o diagnóstico mais provável?', 'Isquemia mesentérica aguda|Colecistite aguda|Diverticulite|Pancreatite aguda', 0, 'A dor intensa desproporcionada aos achados, sobretudo com risco embólico, é clássica de isquemia mesentérica aguda.', 'European Society for Vascular Surgery', 'https://esvs.org/guidelines/', 'Revista'),
('q-004', 'Ginecologia/Obstetrícia', 'Hipertensão na gravidez', 'Média', 'A', 'Gestão do doente', 'Uma grávida de 34 semanas apresenta pressão arterial de 168/112 mmHg e cefaleias persistentes. Qual é a prioridade imediata?', 'Tratar a hipertensão grave e prevenir convulsões|Aguardar proteinúria de 24 horas|Induzir o parto sem estabilização|Reavaliar em consulta dentro de uma semana', 0, 'Hipertensão grave com sintomas neurológicos requer estabilização materna urgente e profilaxia de eclâmpsia.', 'DGS - Saúde materna', 'https://www.dgs.pt/', 'Revista'),
('q-005', 'Psiquiatria', 'Perturbações do humor', 'Média', 'B', 'Diagnóstico', 'Uma pessoa com episódio depressivo refere ideias de morte, plano definido e acesso ao meio. Qual é a resposta mais adequada?', 'Avaliação urgente de risco e garantia de segurança|Iniciar psicoterapia e rever em um mês|Recomendar exercício e higiene do sono|Pedir apenas análises gerais', 0, 'Plano, intenção e acesso ao meio indicam risco elevado, exigindo avaliação urgente e medidas imediatas de segurança.', 'DGS - Saúde mental', 'https://www.dgs.pt/', 'Revista'),
('q-006', 'Medicina', 'Endocrinologia', 'Difícil', 'B', 'Mecanismos da doença', 'Numa pessoa com hiponatremia hipotónica, euvolemia clínica, osmolaridade urinária elevada e função tiroideia normal, qual é a hipótese mais provável?', 'Síndrome de secreção inapropriada de ADH|Diabetes insípida|Hiperaldosteronismo primário|Polidipsia primária', 0, 'A combinação de hiponatremia hipotónica, euvolemia e urina inapropriadamente concentrada é compatível com SIADH após excluir outras causas.', 'European Society of Endocrinology', 'https://www.ese-hormones.org/', 'Revista'),
('q-007', 'Medicina', 'Pneumologia', 'Média', 'A', 'Gestão do doente', 'Uma pessoa com exacerbação de DPOC apresenta acidose respiratória e trabalho respiratório aumentado apesar do tratamento inicial. Qual é o suporte ventilatório preferencial se não houver contraindicações?', 'Ventilação não invasiva|Oxigénio de alto débito isolado|Intubação imediata em todos os casos|Nenhum suporte ventilatório', 0, 'A ventilação não invasiva reduz trabalho respiratório e necessidade de intubação na exacerbação hipercápnica apropriada.', 'GOLD Report', 'https://goldcopd.org/', 'Revista'),
('q-008', 'Pediatria', 'Neonatologia', 'Difícil', 'A', 'Prevenção', 'Qual é a medida mais eficaz para reduzir transmissão vertical de infeção conhecida durante o seguimento pré-natal?', 'Identificação precoce e intervenção específica segundo o agente|Antibiótico universal no terceiro trimestre|Cesariana eletiva em todas as situações|Suspensão universal da amamentação', 0, 'A estratégia depende do agente e começa pelo rastreio e intervenção dirigida, evitando medidas universais sem indicação.', 'DGS - Saúde reprodutiva', 'https://www.dgs.pt/', 'Revista'),
('q-009', 'Cirurgia', 'Trauma', 'Média', 'A', 'Gestão do doente', 'Num traumatizado instável com suspeita de hemorragia intra-abdominal, qual é o exame rápido realizado à cabeceira?', 'Ecografia FAST|Ressonância magnética|Colonoscopia|Cintigrafia', 0, 'A ecografia FAST permite pesquisar rapidamente líquido livre no doente traumatizado instável.', 'European trauma guidance', 'https://www.erc.edu/', 'Revista'),
('q-010', 'Psiquiatria', 'Ansiedade', 'Fácil', 'B', 'Diagnóstico', 'Episódios recorrentes de medo intenso com sintomas autonómicos, início súbito e preocupação persistente com novos episódios sugerem que diagnóstico?', 'Perturbação de pânico|Perturbação obsessivo-compulsiva|Distimia|Delirium', 0, 'Ataques inesperados recorrentes seguidos de preocupação ou alteração comportamental sustentam perturbação de pânico.', 'DGS - Saúde mental', 'https://www.dgs.pt/', 'Revista');
